# type: ignore[call-arg] """For each sequence group, we generate a list of SequenceOutput object,
    each of which contains one possible candidate for the next token.

    This data structure implements methods, so it can be used like a list, but
    also has optional fields for device tensors.
    """ outputs: list[CompletionSequenceGroupOutput] # On-device tensor containing probabilities of each token. sampled_token_probs: Optional[torch.Tensor] = None # On-device tensor containing the logprobs of each token. logprobs: Optional["torch.Tensor"] = None # Holds either (1) the pythonized sampler result (single-step scheduling) # or (2) what will be arguments for later deferred pythonization of the # sampler result (muliti-step scheduling) deferred_sample_results_args: Optional[SampleResultArgsType] = None # On-device tensor containing the sampled token ids. sampled_token_ids: Optional[torch.Tensor] = None # CPU tensor containing the sampled token ids. Used during multi-step to # return the sampled token ids from last rank to AsyncLLMEngine to be # 'broadcasted' to all other PP ranks for next step. sampled_token_ids_cpu: Optional[torch.Tensor] = None # On-device tensor containing the sampled token embeddings (embeddings # corresponding to the sampled token ids). Used when prompt embeddings are # specified in lieu of prompt token ids or text. sampled_token_embeds: Optional[torch.Tensor] = None # Optional last hidden states from the model. hidden_states: Optional[torch.Tensor] = None # Optional prefill hidden states from the model # (used for models like EAGLE). prefill_hidden_states: Optional[torch.Tensor] = None # Time taken in the forward pass for this across all workers model_forward_time: Optional[float] = None # Time taken in the model execute function. This will include model forward, # block/sync across workers, cpu-gpu sync time and sampling time. model_execute_time: Optional[float] = None def __getitem__(self, idx: int) -> CompletionSequenceGroupOutput:
        return self.outputs[idx] def __setitem__(self, idx: int, value):
        self.outputs[idx] = value def __iter__(self) -> Iterator[CompletionSequenceGroupOutput]:
        return iter(self.outputs) def __len__(self):
        return len(self.outputs) def __eq__(self, other: object):
        return isinstance(other,
                          self.__class__) and self.outputs == other.outputs

def load_weights(self, weights: Iterable[tuple[str,
                                                   torch.Tensor]]) -> set[str]:
        loader = AutoWeightsLoader(
            self,
            # With tie_word_embeddings, we can skip lm_head.weight
            # The weight might appear unnecessarily in the files if the model is
            # processed with quantization, LoRA, fine-tuning, etc.
            skip_prefixes=(["lm_head."]
                           if self.config.tie_word_embeddings else None),
        )
        return loader.load_weights(weights)

def load_weights(self, weights: Iterable[tuple[str,
